import math
import torch
import torch.nn as nn
import torch.nn.functional as F

# ---- reference: day1
"""Day 1 reference implementations: loaded as hidden setup for the day-1 exercises (the names in each item's
`targets:` are removed again before the learner's code runs)."""
from dataclasses import dataclass, field, asdict
from pathlib import Path
import functools

CALLS = []   # d1-08: the decorator `logged` appends (name, args, kwargs) here


@dataclass
class TrainConfig:
    lr: float = 3e-4
    batch_size: int = 32
    n_layer: int = 6
    device: str = "cuda"
    betas: tuple = (0.9, 0.95)
    tags: list = field(default_factory=list)   # a mutable default needs default_factory

    def scaled_lr(self, k):
        return self.lr * k


def chunk(seq, n):
    return [seq[i:i + n] for i in range(0, len(seq) - n + 1, n)]


def make_xy(data, i, block_size):
    x = data[i:i + block_size]
    y = data[i + 1:i + 1 + block_size]
    return x, y


def char_freq(text):
    f = {}
    for ch in text:
        f[ch] = f.get(ch, 0) + 1
    return f


def top_k(freq, k):
    return sorted(freq.items(), key=lambda kv: (-kv[1], kv[0]))[:k]


class RunningMean:
    def __init__(self):
        self.reset()

    def reset(self):
        self.total = 0.0
        self.n = 0

    def __call__(self, x):
        self.total += float(x)
        self.n += 1
        return self.value

    @property
    def value(self):
        return self.total / self.n if self.n else 0.0


class EMAMean(RunningMean):
    def __init__(self, decay=0.9):
        super().__init__()
        self.decay = decay
        self._v = None

    def __call__(self, x):
        x = float(x)
        self._v = x if self._v is None else self.decay * self._v + (1 - self.decay) * x
        self.n += 1
        return self._v

    @property
    def value(self):
        return 0.0 if self._v is None else self._v

    def reset(self):
        super().reset()
        self._v = None


class Budget:
    def __init__(self, total_steps, step=0):
        self.total_steps = total_steps
        self.step = step

    @property
    def progress(self):
        return self.step / self.total_steps

    @property
    def done(self):
        return self.step >= self.total_steps


def logged(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        CALLS.append((fn.__name__, args, kwargs))
        return fn(*args, **kwargs)
    return wrapper


def log_line(step, loss, lr, dt):
    return f"step {step:5d} | loss {loss:.4f} | lr {lr:.2e} | {dt * 1000:.1f}ms"


def deltas(xs):
    return [b - a for a, b in zip(xs, xs[1:])]


def label_pairs(names, values):
    return [f"{i}:{n}={v}" for i, (n, v) in enumerate(zip(names, values))]


def ckpt_path(root, run_name, step):
    d = Path(root) / run_name
    d.mkdir(parents=True, exist_ok=True)
    return d / f"ckpt_{step:06d}.pt"


def bucket_by_len(samples, bucket_size=2):
    out = {}                       # a fresh dict on every call (not a mutable default argument)
    for s in samples:
        L = len(s)
        out.setdefault(L, [])
        if len(out[L]) >= bucket_size:
            continue               # bucket full: skip this sample, no error
        out[L].append(s)
    return out

for _name in ['TrainConfig']:
    globals().pop(_name, None)
del _name

d1-01.tests:
@check("all defaults are right")
def t01a():
    c = TrainConfig()
    true(c.lr == 3e-4, f"lr should default to 3e-4, yours: {c.lr!r}")
    true(c.batch_size == 32 and c.n_layer == 6, f"batch_size / n_layer should be 32 / 6, yours: {c.batch_size!r} / {c.n_layer!r}")
    true(c.device == "cuda", f"device should default to 'cuda', yours: {c.device!r}")
    true(c.betas == (0.9, 0.95), f"betas should default to (0.9, 0.95), yours: {c.betas!r}")

@check("two instances do not share one tags list")
def t01b():
    a, b = TrainConfig(), TrainConfig()
    a.tags.append("x")
    true(b.tags == [], "the two instances share the same list: this is exactly why you need field(default_factory=list)")

@check("scaled_lr(k) returns lr * k")
def t01c():
    got = TrainConfig(lr=1e-3).scaled_lr(2)
    true(close(got, 2e-3), f"TrainConfig(lr=1e-3).scaled_lr(2) should be 0.002, yours: {got!r}")

