@check("char_freq counts every character")
def t04a():
    f = char_freq("abracadabra")
    want = {"a": 5, "b": 2, "r": 2, "c": 1, "d": 1}
    true(f == want, f"char_freq('abracadabra') should be {want}, yours: {f}")

@check("top_k: highest count first, ties by character")
def t04b():
    f = {"a": 5, "b": 2, "r": 2, "c": 1, "d": 1}
    got = top_k(f, 3)
    want = [("a", 5), ("b", 2), ("r", 2)]
    true(got == want, f"top_k(f, 3) should be {want}, yours: {got}")

