d6-06.tests:
@check("Gradient accumulation == a big batch")
def t08():
    seed(3)
    model = nn.Linear(6, 4)
    xs, ys = torch.randn(32, 6), torch.randint(0, 4, (32,))

    model.zero_grad()
    F.cross_entropy(model(xs), ys).backward()
    ref = {n: p.grad.clone() for n, p in model.named_parameters()}

    got = grad_accum_step(model, xs, ys, n_micro=4)
    for n in ref:
        eq(got[n], ref[n], tol=1e-5,
           msg=f"the gradient of {n} does not match. Exactly 4 times too big: you forgot to divide by n_micro; off by more: maybe the old gradients were not cleared first")

