# ---- reference: day7
"""Day 7 reference module (latent space and the VAE). Loaded as hidden setup by the day-7 items;
the names an item asks the learner to write are removed again before the learner's code runs."""
import math

import torch
import torch.nn as nn
import torch.nn.functional as F

CONV_SHAPES = {
    (32, 3, 1, 1): 32,
    (32, 4, 2, 1): 16,
    (32, 3, 2, 1): 16,
    (32, 1, 1, 0): 32,
    (7, 3, 2, 0): 3,
}


def conv_out(H, kernel, stride, padding):
    return (H + 2 * padding - kernel) // stride + 1


def reparameterize(mu, logvar):
    std = torch.exp(0.5 * logvar)
    return mu + std * torch.randn_like(std)


def kl_normal(mu, logvar):
    return 0.5 * (mu ** 2 + logvar.exp() - 1 - logvar).flatten(1).sum(1)


class Encoder(nn.Module):
    def __init__(self, z_ch=4):
        super().__init__()
        self.z_ch = z_ch
        self.net = nn.Sequential(
            nn.Conv2d(3, 32, 4, 2, 1), nn.SiLU(),
            nn.Conv2d(32, 64, 4, 2, 1), nn.SiLU(),
            nn.Conv2d(64, 2 * z_ch, 3, 1, 1),
