@check("stops when the stop token fires")
def t09():
    calls = {"n": 0}

    def step(prev):
        calls["n"] += 1
        t = prev.size(1)
        stop = torch.tensor([10.0]) if t >= 4 else torch.tensor([-10.0])
        return torch.full((1, 3), float(t)), stop

    out = ar_decode(step, 3, max_steps=20)
    shape_is(out, (1, 4, 3),
             "the stop fires on step 4, so there should be 4 frames (with the one that triggered the stop, without the go frame). Never stops? Check that the new frame is appended to prev")
    eq(out[0, 0], torch.ones(3), msg="on the first call prev should hold only the go frame (t=1)")
    true(calls["n"] == 4, f"step should be called 4 times, it was called {calls['n']} times")

@check("max_steps stops a model that never says stop")
def t09b():
    never_stop = lambda prev: (torch.zeros(1, 3), torch.tensor([-10.0]))
    shape_is(ar_decode(never_stop, 3, max_steps=7), (1, 7, 3), "a model that never stops must be cut off after max_steps steps")

