    """log(x): negative inputs give nan, 0 gives -inf."""

    def forward(self, x):
        return torch.log(x)


class Exp(nn.Module):
    """exp(x): inputs above about 88.7 give inf in float32."""

    def forward(self, x):
        return torch.exp(x)


class Scale(nn.Module):
    """Multiplies by a constant (like a badly chosen temperature or init scale)."""

    def __init__(self, s):
        super().__init__()
        self.s = s

    def forward(self, x):
        return x * self.s


