@check("the backbone stays frozen")
def _():
    x, y = toy_data(32)
    model = TinyNet(c=10)
    before = {k: v.clone() for k, v in model.backbone.state_dict().items()}
    finetune_new_head(model, x, y, num_classes=4, steps=20, lr=0.5)
    true(all(not p.requires_grad for p in model.backbone.parameters()),
         "the backbone's parameters should have requires_grad=False")
    for k, v in model.backbone.state_dict().items():
        eq(v, before[k], tol=0, msg=f"backbone.{k} changed: keep the backbone frozen and train only the new head")

