def _():
    loss = lm_loss(NextModel(11), _counting_tokens())
    true(loss.item() < 0.01,
         f"loss = {loss.item():.3f}. NextModel always guesses the next token right, so the loss should be close to 0. "
         "Are you comparing the output at position t with the token at position t?")

@check("a model that copies the current token must not get a loss close to 0")
def _():
    loss = lm_loss(CopyModel(11), _counting_tokens())
    true(loss.item() > 1.0,
         f"loss = {loss.item():.4f}. A model that only copies got an almost perfect loss, too good to be true: the labels are not shifted, so the model is copying the answer.")

