    return True


def check_batch_independent(f, x):
    h = x.shape[0] // 2
    with torch.no_grad():
        whole = f(x)
        parts = torch.cat([f(x[:h]), f(x[h:])])
    return torch.allclose(parts, whole, atol=1e-5)

