import hashlib
import json

V = {"<pad>": 0, "<eos>": 1, "hello": 2, "world": 3, "你好": 4}


@check("same vocabulary in another insertion order, same fingerprint")
def _():
    fp = vocab_fingerprint(V)
    true(isinstance(fp, str) and len(fp) == 16, f"return a string of 16 characters; you returned {fp!r}")
    shuffled = dict(reversed(list(V.items())))
    true(vocab_fingerprint(shuffled) == fp, "only the insertion order changed, yet the fingerprint changed: use json.dumps with sort_keys=True")


@check("computed the required way (training and serving processes agree)")
def _():
    want = hashlib.sha256(json.dumps(V, sort_keys=True).encode("utf-8")).hexdigest()[:16]
    true(vocab_fingerprint(V) == want,
         "the fingerprint is not the first 16 characters of sha256(json.dumps(vocab, sort_keys=True)). "
         "If you used hash(): it changes every time Python starts, so training and serving would never agree")


@check("any change to a token or an id changes the fingerprint")
def _():
    fp = vocab_fingerprint(V)
    swapped = dict(V, hello=3, world=2)
    added = dict(V, new_word=5)
