def _blocks():
    seed(0)
    return nn.ModuleList([nn.Sequential(nn.Linear(16, 64), nn.GELU(), nn.Dropout(0.1), nn.Linear(64, 16))
                          for _ in range(4)])

def _plain(blocks, x):
    for b in blocks:
        x = b(x)
    return x

def _grads(f, blocks, x):
    blocks.zero_grad()
    seed(1)                          # same random seed -> same dropout masks
    f(blocks, x).pow(2).mean().backward()
    return [None if p.grad is None else p.grad.clone() for p in blocks.parameters()]

@check("same output as the plain forward pass")
def _():
    blocks = _blocks()
    x = torch.randn(8, 16)
    seed(1)
    want = _plain(blocks, x)
    seed(1)
    got = forward_checkpointed(blocks, x)
    eq(got, want, tol=1e-6, msg="the result changed. Checkpointing does not change the math: run every block, in order")

@check("x needs no gradients: parameter gradients still identical")
def _():
    blocks = _blocks()
    x = torch.randn(8, 16)          # plain data, no gradients needed
    want = _grads(_plain, blocks, x)
    try:
        got = _grads(forward_checkpointed, blocks, x)
    except RuntimeError as e:
        raise AssertionError(f"backward failed: {str(e)[:70]}. When no input needs gradients, use_reentrant=True (also what you get "
                             "when you leave it out) gives this part no gradients: pass use_reentrant=False")
    for i, (g, w) in enumerate(zip(got, want)):
        true(g is not None, f"parameter {i} has no gradient: use use_reentrant=False")
        eq(g, w, tol=1e-6, msg=f"the gradient of parameter {i} differs from the one without checkpointing")

@check("less than half the bytes saved for backward")
def _():
    blocks = _blocks()
    x = torch.randn(8, 16)
    _, plain_n = saved_bytes(_plain, blocks, x, skip=blocks.parameters())
    _, ck_n = saved_bytes(forward_checkpointed, blocks, x, skip=blocks.parameters())
    true(ck_n < plain_n / 2, f"without checkpointing {plain_n} bytes were saved, yours saved {ck_n}: wrap every block in checkpoint")

