import os, tempfile

def _v1_file(folder, drop=None):
    """Make a v1 checkpoint: weights from a Net, but the last layer is called classifier. Returns (path, original model)."""
    torch.manual_seed(7)
    net = Net().eval()
    sd = {("classifier." + k.removeprefix("head.")) if k.startswith("head.") else k: v
          for k, v in net.state_dict().items()}
    if drop:
        del sd[drop]
    path = os.path.join(folder, "v1.pt")
    torch.save(sd, path)
    return path, net

