def _clip_ref(x, max_norm):
    """The original row-by-row version (used only in PyTorch, to check answers)."""
    out = x.clone()
    for i in range(len(x)):
        n = x[i].norm()
        if n > max_norm:
            out[i] = x[i] * (max_norm / n)
    return out

