        self.max_waiting = max_waiting
        self.timeout_ms = timeout_ms
        self.waiting = []

    def submit(self, x):
        t = Ticket(x, self.clock())
        if len(self.waiting) >= self.max_waiting:
            t.status = 503
        else:
            self.waiting.append(t)
        return t

    def run_next(self):
        if not self.waiting:
            return None
        t = self.waiting.pop(0)
        if self.clock() - t.arrived > self.timeout_ms:
            t.status = 504
            return t
        try:
            t.result = self.model_fn(t.x)
            t.status = 200
        except Exception:
            t.status = 500
        return t


# ---------------------------------------------------------------- latency percentiles / 延迟百分位数
def latency_report(times_ms):
    s = sorted(times_ms)
    n = len(s)

    def pick(q):
        k = math.ceil(q * n / 100)
        return s[max(k, 1) - 1]

    return {"p50": pick(50), "p95": pick(95), "p99": pick(99)}


# ---------------------------------------------------------------- micro-batching / 微批处理
class BatchRecorder:
    """把 fn 包一层，记下每一批的大小（sizes）。 Wraps fn and records the size of every batch (sizes)."""

    def __init__(self, fn):
        self.fn = fn
        self.sizes = []

    def __call__(self, xb):
        self.sizes.append(xb.shape[0])
        return self.fn(xb)


class MicroBatcher:
    def __init__(self, run_batch, max_batch, max_wait_ms, clock):
        self.run_batch = run_batch
        self.max_batch = max_batch
        self.max_wait_ms = max_wait_ms
        self.clock = clock
        self.pending = []

    def submit(self, x):
        t = Ticket(x, self.clock())
        self.pending.append(t)
        if len(self.pending) >= self.max_batch:
            self.flush()
        return t

    def poll(self):
        if self.pending and self.clock() - self.pending[0].arrived >= self.max_wait_ms:
            self.flush()

    def flush(self):
        if not self.pending:
            return
        batch, self.pending = self.pending, []
        out = self.run_batch(torch.stack([t.x for t in batch]))
        for t, y in zip(batch, out):
            t.result = y
            t.status = 200

for _name in ['create_app']:
    globals().pop(_name, None)
del _name

