ROWS = [[5.1, 3.5, 1.4, 0.2]]
SECRET = "CUDA out of memory (weights: /srv/models/iris-v3/model.pt)"

def _predict(rows):
    if rows[0][0] == 999:
        raise RuntimeError(SECRET)
    return reference_probs(rows).tolist()

def _client(ready):
    state = ServiceState(_predict, ready=ready)
    return state, TestClient(create_status_app(state), raise_server_exceptions=False)

@check("ready: /health and /predict both answer 200")
def _():
    state, client = _client(ready=True)
    r = client.get("/health")
    true(r.status_code == 200 and r.json() == {"status": "ok"}, f"/health answered {r.status_code} {r.text}")
    r = client.post("/predict", json={"rows": ROWS})
    true(r.status_code == 200, f"/predict answered {r.status_code}")
    eq(torch.tensor(r.json()["probs"]), reference_probs(ROWS), tol=1e-5, msg="wrong probs")

@check("not ready: /health answers 503")
def _():
    state, client = _client(ready=False)
    r = client.get("/health")
    true(r.status_code == 503, f"the model is still loading, yet /health answered {r.status_code}. Load balancers only look at the status code: answer 200 and they send traffic.")
    state.ready = True
    r = client.get("/health")
    true(r.status_code == 200, f"once state.ready is True, /health should answer 200; yours answered {r.status_code}")

@check("not ready: /predict answers 503 with Retry-After")
def _():
    state, client = _client(ready=False)
    r = client.post("/predict", json={"rows": ROWS})
    true(r.status_code == 503, f"the model is not ready, and /predict answered {r.status_code}, expected 503")
    ra = r.headers.get("retry-after")
    true(ra is not None and ra.strip().isdigit() and int(ra) > 0, f"a 503 should carry a Retry-After header (a positive whole number of seconds); yours is {ra!r}")

@check("model error: answers 500, leaks no details, keeps working")
def _():
    state, client = _client(ready=True)
    r = client.post("/predict", json={"rows": [[999, 1.0, 1.0, 1.0]]})
    true(r.status_code == 500, f"the model raised an exception, yet the answer was {r.status_code}, expected 500")
    true("/srv/models" not in r.text and "out of memory" not in r.text, f"the exception's text was sent to the client: {r.text}. Details go to the server's log; the client only gets internal error.")
    r = client.post("/predict", json={"rows": ROWS})
    true(r.status_code == 200, f"after one error, a normal request got {r.status_code}")

