    n = len(s)

    def pick(q):
        k = math.ceil(q * n / 100)
        return s[max(k, 1) - 1]

    return {"p50": pick(50), "p95": pick(95), "p99": pick(99)}


# ---------------------------------------------------------------- micro-batching / 微批处理
class BatchRecorder:
    """把 fn 包一层，记下每一批的大小（sizes）。 Wraps fn and records the size of every batch (sizes)."""

    def __init__(self, fn):
        self.fn = fn
        self.sizes = []

    def __call__(self, xb):
        self.sizes.append(xb.shape[0])
        return self.fn(xb)


class MicroBatcher:
    def __init__(self, run_batch, max_batch, max_wait_ms, clock):
        self.run_batch = run_batch
        self.max_batch = max_batch
        self.max_wait_ms = max_wait_ms
        self.clock = clock
        self.pending = []

    def submit(self, x):
        t = Ticket(x, self.clock())
        self.pending.append(t)
        if len(self.pending) >= self.max_batch:
            self.flush()
        return t

    def poll(self):
        if self.pending and self.clock() - self.pending[0].arrived >= self.max_wait_ms:
            self.flush()

    def flush(self):
        if not self.pending:
            return
        batch, self.pending = self.pending, []
        out = self.run_batch(torch.stack([t.x for t in batch]))
        for t, y in zip(batch, out):
            t.result = y
            t.status = 200

for _name in ['RequestQueue']:
    globals().pop(_name, None)
del _name

