def _shuffled(values):
    return [values[i] for i in torch.randperm(len(values)).tolist()]

def _expect(times, want, why=""):
    got = latency_report(times)
    true(isinstance(got, dict), f"should return a dict, you returned a {type(got).__name__}")
    for key in ("p50", "p95", "p99"):
        true(key in got, f"{key!r} is missing from the returned dict")
        true(close(got[key], want[key]), f"{key}: yours is {got[key]}, expected {want[key]}. {why}")

@check("1 to 100: p50 = 50, p95 = 95, p99 = 99")
def _():
    _expect(_shuffled(list(range(1, 101))), {"p50": 50, "p95": 95, "p99": 99},
            "Sort first; k = math.ceil(q * n / 100), take s[k - 1].")

@check("20 requests with two slow ones in the tail")
def _():
    times = _shuffled([12.0] * 9 + [15.0] * 9 + [200.0, 900.0])
    _expect(times, {"p50": 15.0, "p95": 200.0, "p99": 900.0},
            "n = 20: p50 takes value number 10, p95 number 19, p99 number 20. If you got 235.0 or 767.0, that is linear interpolation (the numpy / torch.quantile default); this item wants nearest-rank.")

