    def forward(self, ids, cache=None):
        step = len(self.calls)
        self.calls.append(ids.shape[1])
        logits = torch.zeros(ids.shape[0], ids.shape[1], self.vocab)
        logits[:, -1, self.script[min(step, len(self.script) - 1)]] = 5.0
        return logits, {"calls": step + 1}


