def greedy_no_cache(model, prompt_ids, n):
    """参考答案：每一步都把整个序列重新算一遍（慢，但一定对）。 Reference: recompute the whole sequence every step."""
    ids, out = prompt_ids, []
    for _ in range(n):
        logits, _ = model(ids)
        tok = logits[0, -1].argmax().item()
        out.append(tok)
        ids = torch.cat([ids, torch.tensor([[tok]])], dim=1)
    return out


