        logits, cache = model(ids, cache)            # first call: prefill the prompt; then: decode one token
        tok = logits[0, -1].argmax().item()
        if tok == eos_id:
            return
        yield tok
        ids = torch.tensor([[tok]], device=prompt_ids.device)


class CountingIter:
