        self.taken = 0

    def __iter__(self):
        return self

    def __next__(self):
        x = next(self._it)
        self.taken += 1
        return x


def text_until_stop(pieces, stops):
    text = ""
    for piece in pieces:
        text += piece
        hits = [text.find(s) for s in stops if s in text]
        if hits:
            return text[:min(hits)]
    return text


def held_back(text, stops):
    """text 末尾最长的、可能是某个 stop 开头的那一段的长度。
