    keep = 0
    for s in stops:
        for k in range(min(len(s) - 1, len(text)), 0, -1):
            if text.endswith(s[:k]):
                keep = max(keep, k)
                break
    return keep


def stream_until_stop(pieces, stops):
    buf = ""
    for piece in pieces:
        buf += piece
        hits = [buf.find(s) for s in stops if s in buf]
        if hits:
            if buf[:min(hits)]:
                yield buf[:min(hits)]
            return
        keep = held_back(buf, stops)
        if len(buf) > keep:
