    def __init__(self, ch=4, hidden=32):
        super().__init__()
        self.net = nn.Sequential(nn.Conv2d(ch, hidden, 3, padding=1), nn.SiLU(),
                                 nn.Conv2d(hidden, hidden, 3, padding=1), nn.SiLU(),
                                 nn.Conv2d(hidden, ch, 3, padding=1))

    def forward(self, x):
        return self.net(x)

