        ids = torch.tensor([[tok]], device=prompt_ids.device)


class CountingIter:
    """包一层迭代器，记下被读走了几个元素。 Wraps an iterable and counts how many items were taken."""

    def __init__(self, items):
        self._it = iter(items)
        self.taken = 0

    def __iter__(self):
        return self

    def __next__(self):
        x = next(self._it)
        self.taken += 1
        return x


