                                 nn.Conv2d(hidden, hidden, 3, padding=1), nn.SiLU(),
                                 nn.Conv2d(hidden, ch, 3, padding=1))

    def forward(self, x):
        return self.net(x)

for _name in ['validate_sampling']:
    globals().pop(_name, None)
del _name

