# ---------------------------------------------------------------- a tiny random causal LM with a KV cache
class _Block(nn.Module):
    """Pre-norm Transformer block with GQA attention: n_heads query heads share n_kv_heads k/v heads."""

    def __init__(self, d, n_heads, n_kv_heads):
        super().__init__()
